import { Group, Mesh, PlaneGeometry, BoxGeometry, Texture, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, color, texture, fract, sin, dot, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();
  group.name = 'collection-title';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- Engineered gradient + grain plane ----
  const planeW = 3.4;
  const planeH = 1.05;
  const geometry = new PlaneGeometry(planeW, planeH, 1, 1);

  // Placeholder texture that will be mutated once the real image resolves.
  const placeholderTex = new Texture();
  placeholderTex.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const topColor = color(colors.ink);
  const bottomColor = color(colors.surface);
  const gradientNode = mix(topColor, bottomColor, uvNode.y);

  // simple hash-based grain, static (no time uniform -> no motion, per "static composition")
  const p = uvNode.mul(512.0);
  const grainRaw = fract(sin(dot(p, vec2(12.9898, 78.233))).mul(43758.5453));
  const grainNode = grainRaw.sub(0.5).mul(0.035);

  const imgNode = texture(placeholderTex);
  const withImage = mix(gradientNode, imgNode.rgb, float(0.12));

  const material = new MeshBasicNodeMaterial();
  material.side = DoubleSide;
  material.colorNode = withImage.add(vec3(grainNode, grainNode, grainNode));

  const plane = new Mesh(geometry, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // load real image asynchronously (via ctx loader only) and mutate placeholder
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      placeholderTex.image = tex.image;
      placeholderTex.colorSpace = tex.colorSpace ?? THREE.SRGBColorSpace;
      placeholderTex.wrapS = tex.wrapS;
      placeholderTex.wrapT = tex.wrapT;
      placeholderTex.needsUpdate = true;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- accent underline (thin, <=10% of frame) ----
  const underlineGeo = new BoxGeometry(0.9, 0.03, 0.02);
  const underlineMat = new MeshBasicNodeMaterial();
  underlineMat.colorNode = color(colors.accent);
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(-1.05, -0.32, 0.02);
  group.add(underline);

  // ---- headline text "Collection" ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Collection', typography: { fontSize: 96 } };

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: headlineItem.typography?.fontSize ?? 96,
    color: colors.paper,
    align: 'left',
  });
  headline.position.set(-1.55, -0.02, 0.03);
  group.add(headline);

  // ---- entrance motion: weighted-settle, translate + scale, <=0.4 units, power3/power4 ----
  group.position.set(0, 0.4, 0);
  group.scale.set(0.98, 0.98, 0.98);

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  tl.to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.05);

  // ---- cleanup ----
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    tl.kill();
    geometry.dispose();
    material.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    placeholderTex.dispose();
    if (headline?.geometry) headline.geometry.dispose?.();
    if (headline?.material) headline.material.dispose?.();
  };

  return group;
}
